import { StyleFn } from "..";

export const FormControl: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;

  return {
    root: {
      display: "block",
      "&:not(:last-child)": {
        marginBottom: size.spacing[16],
      },
    },
    control: {
      width: "100%",
    },
    label: {
      display: "flex",
      position: "relative",
      marginBottom: size.spacing[8],
      fontFamily: "inherit",
      fontSize: font.size.small,
      fontWeight: font.weight.medium,
      lineHeight: font.lineheight.medium,
      color: color.text.neutral.strong[mode],
      "& > button": {
        marginLeft: size.spacing[4],
      },
    },
    info: {
      position: "absolute",
      right: 0,
      "& + $optional": {
        paddingRight: size.spacing[24],
        marginRight: size.spacing[4],
      }
    },
    optional: {
      flex: 1,
      textAlign: "right",
      lineHeight: font.lineheight.xsmall,
      marginTop: size.spacing[4],
      marginLeft: size.spacing[4],
      fontSize: font.size.xsmall,
      fontWeight: font.weight.regular,
      color: color.text.neutral.strong[mode],
    },
    help: {
      display: "flex",
      marginTop: size.spacing[4],
      fontFamily: "inherit",
      fontSize: font.size.xsmall,
      lineHeight: font.lineheight.xsmall,
      color: color.text.neutral.strong[mode],
    },
    helplink: {
      flex: 1,
      textAlign: "right",
      marginTop: `calc(-${size.spacing[4]})`,
    },
    _info: {
      "& $help": {
        color: color.text.feedback.information.default[mode],
      },
    },
    _error: {
      "& $help": {
        color: color.text.feedback.error.default[mode],
      },
    },
    _success: {
      "& $help": {
        color: color.text.feedback.success.default[mode],
      },
    },
  };
};
